{"id": "4b67bed9-06da-40b2-a306-24e9e7dfd390", "shortKey": "canonical_math_sek1_j5_integers_add", "title": "Ganze Zahlen addieren", "description": "Die lernende Person kann Additionsaufgaben mit ganzen Zahlen sicher lösen, Rechenschritte begründen und Ergebnisse an der Zahlengeraden oder im Sachkontext prüfen.", "descriptionEn": "The learner can reliably solve addition tasks with integers, justify calculation steps, and check results on the number line or in context.", "requires": ["d07ef7b1-8bd2-56e0-9e74-d90c3c3e02fe", "d825f7ce-e19b-594a-8181-eff199c21d93"], "phase": null}
