{"id": "8aff7aac-321b-5172-ac55-877876bfd2cd", "shortKey": null, "title": "Messabweichungen und Fehlerarten unterscheiden", "description": "Die lernende Person kann Messabweichungen systematisch erfassen und systematische von zufälligen Fehlern unterscheiden.", "descriptionEn": "The learner can systematically identify measurement deviations and distinguish systematic from random errors.", "requires": ["5c44b9ba-9b05-4774-95d5-073230d3fc4f"], "phase": null}
SOURCE: curricula/DE/Gymnasium/canonical/DE_DEU_S_GYM_CANONICAL_PHYSIK.de.json
{"id": "8d1bb6ce-2433-4637-94ba-3bdc35fa5b10", "shortKey": "canonical_math_refute_integer_statements_with_counterexamples", "title": "Aussagen über ganze Zahlen prüfen und mit Gegenbeispielen widerlegen", "description": "Die lernende Person kann Aussagen über ganze Zahlen prüfen, wahre Aussagen allgemein begründen und falsche Aussagen mit passenden Gegenbeispielen widerlegen.", "descriptionEn": "The learner can check statements about integers, justify true statements generally, and refute false statements with suitable counterexamples.", "requires": ["3fde4db5-9e92-5f3a-98e1-d386a42b9e01"], "phase": null}
