{"id": "971beafa-6ba5-4c82-ac8b-7ebf66eec3dd", "shortKey": "canonical_physics_uniform_motion", "title": "Gleichförmige Bewegung und Geschwindigkeit", "description": "Die lernende Person kann gleichförmige Bewegungen im Diagramm erkennen, die Geschwindigkeit definieren und den Geschwindigkeitsbetrag experimentell bestimmen.", "descriptionEn": "The learner can recognize uniform motions in the diagram, define velocity, and experimentally determine the magnitude of velocity.", "requires": ["ce431132-dfc4-42c2-aff6-bd72035190f8", "af3d6bff-c5fb-4ec6-a9f0-c0be09fc9186"], "phase": null}
